const N = 100_000

export default defineProblem({
  signature: {
    kind: 'function',
    name: 'lengthOfLIS',
    params: [{ name: 'nums', type: 'int[]' }],
    returns: 'int',
  },
  examples: [
    {
      args: [[3, 1, 4, 1, 5, 9, 2, 6]],
      expected: 4,
      explanation: 'For example [1,4,5,9] or [3,4,5,6]. No increasing subsequence has 5 elements.',
    },
    {
      args: [[2, 8, 3, 9, 4, 10, 5, 11]],
      expected: 5,
      explanation: '[2,3,4,5,11].',
    },
    {
      args: [[5, 5, 5]],
      expected: 1,
      explanation: 'The subsequence must be strictly increasing.',
    },
  ],
  tests: [
    ...hiddenTests,
    // The O(n²) dynamic program times out on these.
    { args: [Array.from({ length: N }, (_, i) => i)], expected: N },
    { args: [Array.from({ length: N }, (_, i) => N - i)], expected: 1 },
    { args: [Array.from({ length: N }, (_, i) => ((i * 7919) % 100_003) - 50_000)], expected: 306 },
  ],
  solution: {
    javascript: `function lengthOfLIS(nums) {
  // tails[k] = smallest possible last value of an increasing subsequence of length k + 1.
  const tails = []
  for (const x of nums) {
    // First tail >= x: x extends everything shorter, and replaces that tail.
    let lo = 0
    let hi = tails.length
    while (lo < hi) {
      const mid = (lo + hi) >> 1
      if (tails[mid] < x) lo = mid + 1
      else hi = mid
    }
    tails[lo] = x
  }
  return tails.length
}`,
    python: `class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # tails[k] = smallest possible last value of an increasing subsequence of length k + 1.
        tails = []
        for x in nums:
            # First tail >= x: x extends everything shorter, and replaces that tail.
            i = bisect_left(tails, x)
            if i == len(tails):
                tails.append(x)
            else:
                tails[i] = x
        return len(tails)`,
  },
})
